from pathlib import Path
p=Path('app/page.tsx'); s=p.read_text(encoding='utf-8-sig')
s=s.replace("let profile: any, experiences: any[] = [], competencies: any[] = [], workflows: any[] = [], samples: any[] = [], skills: any[] = [], testimonials: any[] = []", "let profile: any, experiences: any[] = [], competencies: any[] = [], workflows: any[] = [], samples: any[] = [], skills: any[] = [], testimonials: any[] = [], education: any[] = [], certificates: any[] = []")
s=s.replace("[profile, experiences, competencies, workflows, samples, skills, testimonials] = await Promise.all([\n      getPortfolio(), getCollection('experiences'), getCollection('competencies'), getCollection('workflows'), getCollection('samples'), getCollection('skills'), getCollection('testimonials'),\n    ])", "[profile, experiences, competencies, workflows, samples, skills, testimonials, education, certificates] = await Promise.all([\n      getPortfolio(), getCollection('experiences'), getCollection('competencies'), getCollection('workflows'), getCollection('samples'), getCollection('skills'), getCollection('testimonials'), getCollection('education'), getCollection('certificates'),\n    ])")
s=s.replace("const cv = profile?.[admin ? 'cvAdmin' : 'cvSales']", "const cv = profile?.[admin ? 'cvAdmin' : 'cvSales']\n  const cvHref = cv?.id ? `/api/cv?id=${encodeURIComponent(String(cv.id))}` : '/CV-Sintia-Marada-Hutagalung.pdf'")
s=s.replace("href={cv?.id ? `/api/cv?id=${encodeURIComponent(String(cv.id))}` : '#kontak'}", "href={cvHref}")
s=s.replace("{cv?.id && <a className=\"button outline\" href={`/api/cv?id=${encodeURIComponent(String(cv.id))}`}>Download CV {admin ? 'Admin' : 'Sales'} <span>↓</span></a>}", "<a className=\"button outline\" href={cvHref} download>Download CV {admin ? 'Admin' : 'Sales'} <span>↓</span></a>")
s=s.replace("<p>{item.summary}</p>{item.achievements?.length > 0", "<p>{item.summary}</p>{item.responsibilities?.length > 0 && <ul className=\"responsibility-list\">{item.responsibilities.map((point: any) => <li key={point.id || point.detail}>{point.detail}</li>)}</ul>}{item.achievements?.length > 0")
old="""{trackSamples.length ? trackSamples.map((sample: any) => <article className=\"sample-card\" key={sample.id}><div className=\"sample-thumbnail\">{mediaUrl(sample.preview) ? <img src={mediaUrl(sample.preview)} alt={sample.preview?.alt || sample.title} /> : <div className=\"sheet-preview\"><span>{sample.title}</span><i /><i /><i /><i /><i /></div>}<span className=\"file-badge\">{sample.document?.mimeType?.includes('pdf') ? 'PDF' : 'SAMPLE'}</span></div><div className=\"sample-info\"><small>{(sample.track || []).includes('admin') ? 'ADMIN' : 'SALES'}</small><h3>{sample.title}</h3><p>{sample.description}</p>{mediaUrl(sample.document) && <a href={mediaUrl(sample.document)} target=\"_blank\" rel=\"noreferrer\">Buka dokumen ↗</a>}</div></article>) : <article className=\"sample-card sample-empty\"><div className=\"sheet-preview\"><span>{admin ? 'Rekap pencapaian dealer' : 'Tracker lead & follow-up'}</span><i /><i /><i /><i /><i /></div><div className=\"sample-info\"><small>TEMPLATE DEMONSTRASI</small><h3>{admin ? 'Contoh rekap administrasi' : 'Contoh tracker sales'}</h3><p>Unggah pratinjau dan berkas contoh yang sudah dianonimkan melalui CMS.</p></div></article>}"""
new="""{trackSamples.length ? trackSamples.map((sample: any) => <article className=\"sample-card\" key={sample.id}><div className=\"sample-thumbnail\">{mediaUrl(sample.preview) ? <img src={mediaUrl(sample.preview)} alt={sample.preview?.alt || sample.title} /> : <div className=\"sheet-preview\"><span>{sample.title}</span><i /><i /><i /><i /><i /></div>}<span className=\"file-badge\">{sample.document?.mimeType?.includes('pdf') ? 'PDF' : 'SAMPLE'}</span></div><div className=\"sample-info\"><small>{(sample.track || []).includes('admin') ? 'ADMIN' : 'SALES'}</small><h3>{sample.title}</h3><p>{sample.description}</p>{mediaUrl(sample.document) && <a href={mediaUrl(sample.document)} target=\"_blank\" rel=\"noreferrer\">Buka dokumen ↗</a>}</div></article>) : <div className=\"samples-empty\"><b>Belum ada sampel dokumen di CV.</b><span>Tambahkan contoh kerja yang sudah dianonimkan melalui panel admin jika ingin menampilkannya.</span></div>}"""
