marker="    <section className=\"content-section testimonial-section section-anchor\" id=\"testimoni\">"
addition='''    <section className="content-section education-section" id="pendidikan"><div className="section-heading"><div><span className="section-kicker">PENDIDIKAN & PELATIHAN</span><h2>Fondasi akademik<br/><em>dan sertifikasi.</em></h2></div><p>Latar belakang akuntansi memperkuat ketelitian dalam mengelola laporan, data, dan proses penjualan.</p></div><div className="credential-grid"><article className="education-card"><span className="credential-icon">▤</span><small>PENDIDIKAN</small>{education.map((item: any) => <div key={item.id}><h3>{item.qualification}</h3><b>{item.institution}</b><p>{item.startDate} — {item.endDate} · {item.detail}</p></div>)}{education.length === 0 && <div><h3>Bachelor of Accounting and Business/Management</h3><b>STIE Indonesia Jakarta</b><p>2019 — 2023 · GPA 3.59/4.00</p></div>}</article><article className="certificates-card"><span className="credential-icon">✦</span><small>SERTIFIKAT</small><div className="certificate-list">{(certificates.length ? certificates : [{id:'a1',title:'Accurate Accounting Software Training',issuer:'STEI',year:'2022'},{id:'a2',title:'Brevet Pajak',issuer:'STEI',year:'2022'},{id:'a3',title:'Pelatihan Kepemimpinan & Inovasi Mahasiswa STEI',issuer:'STEI',year:'2023'},{id:'a4',title:'Prepare The Future: Unlock Your Passion and Let’s Know Yourself',issuer:'STEI',year:'2023'}]).map((item: any) => <div className="certificate-item" key={item.id}><span>✓</span><p><b>{item.title}</b><small>{item.issuer} · {item.year}</small></p></div>)}</div></article></div></section>

'''
